#include <iostream>
using namespace std;

int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int lcm(int a, int b) {
    return (a * b) / gcd(a, b);
}

int main() {
    int pairs[][2] = {{48, 18}, {100, 75}, {17, 19}};

    cout << "最大公约数和最小公倍数:" << endl;
    for (int i = 0; i < 3; i++) {
        int a = pairs[i][0];
        int b = pairs[i][1];
        cout << "GCD(" << a << ", " << b << ") = " << gcd(a, b) << endl;
        cout << "LCM(" << a << ", " << b << ") = " << lcm(a, b) << endl;
        cout << endl;
    }

    return 0;
}
